import{_ as t,c as n,j as e,a as l,o as _}from"./chunks/framework.CqbvlPrP.js";const u=JSON.parse('{"title":"第一百零二章 七颗绿豆大小的石头","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/102第一百零二章 七颗绿豆大小的石头.md","filePath":"meditation/巴利文大藏经/102第一百零二章 七颗绿豆大小的石头.md"}'),r={name:"meditation/巴利文大藏经/102第一百零二章 七颗绿豆大小的石头.md"};function o(s,a,i,d,p,c){return _(),n("div",null,a[0]||(a[0]=[e("h1",{id:"第一百零二章-七颗绿豆大小的石头",tabindex:"-1"},[l("第一百零二章 七颗绿豆大小的石头 "),e("a",{class:"header-anchor",href:"#第一百零二章-七颗绿豆大小的石头","aria-label":'Permalink to "第一百零二章 七颗绿豆大小的石头"'},"​")],-1),e("p",null,"完全读懂巴利文大藏经",-1),e("p",null,"相应部13相应11经/山经第三(现观相应/因缘篇/如来记说)",-1),e("p",null,"有个时候，佛陀住在舍卫城的祇树林给孤独园。有一天，佛陀对出家弟子们说：“弟子们，如果有个男子在世间最高大的须弥山旁边放置七颗绿豆大小的石头，弟子们，你们现在是怎么想的？是世间最高大的须弥山上的石头更多，还是七颗绿豆大小的石头的更多？”",-1),e("p",null,"出家弟子们回答：“世尊，当然是须弥山上的石头更多，七颗绿豆大小的石头更少，世间最高大的须弥山上的石头是七颗绿豆大小石头的百倍、千倍、十万倍、无数倍。七颗绿豆大小的石头与世间最高大的须弥山上的石头相比可以忽略不计。”",-1),e("p",null,"佛陀说：“同样的道理，弟子们，其他外教的出家人，婆罗门修行人，外教的行脚、游方修行人，他们证悟的果位和境界比不上已经具足如来正法，已经具足如来正确见解的圣弟子们证悟果位和境界的百分之一、千分之一、十万分之一。弟子们，具足如来正法，具足如来正确见解的圣弟子们就能证得这么大的果位，就能开启这么大的智慧，就能达到如此高的解脱境界。",-1),e("p",null,"弟子们，具足正确见解，已经证悟初果（初果解释，见第七十章）及以上果位的圣弟子们，他们灭尽、灭除的烦恼和痛苦很多，他们灭尽的烦恼和痛苦就如同世间最高大的须弥山上的石头那样多，他们残留的烦恼和痛苦非常的少，他们残留的烦恼和痛苦就如同七颗绿豆大小的石头那样少。弟子们，也就是说已经证悟初果的圣弟子们，他们残留的烦恼和痛苦比不上他们灭尽烦恼和痛苦的百分之一、千分之一、十万分之一，他们残留的烦恼和痛苦与他们灭尽的烦恼和痛苦相比可以忽略不计。这些已经证悟初果的圣弟子们，他们最多在人间和天界往返七次，就能永远的从生死轮回中解脱出来，也就是说已经证悟初果的圣弟子们，他们最多再有七次的生死轮回，就能除灭一切的烦恼和痛苦，就能从这个世间永远的解脱出来，就能从生死轮回中永远的解脱出来。弟子们，具足正确的见解，证悟初果就能获得这么大的功德利益，明白了如来所说的正法，就能获得这么大的功德利益。”",-1),e("p",null,"佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。",-1)]))}const f=t(r,[["render",o]]);export{u as __pageData,f as default};
